public
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case AudioRead(message: String
    )
    case UnsupportedAudio(message: String
    )
    case Resample(message: String
    )
    case ModelLoad(message: String
    )
    case Inference(message: String
    )
    case InputTooLong(message: String
    )
    case IncompleteOutput(kind: IncompleteOutputKind, partialText: String?
    )
    case Cancelled(partialText: String?
    )
    case FileHash(message: String
    )
    case FileSizeMismatch(expected: UInt64, actual: UInt64
    )
    case FileHashMismatch(expected: String, actual: String
    )
    case InvalidExpectedSha256(message: String
    )
    case InvalidModelPackageManifest
    case Busy






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .AudioRead(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .UnsupportedAudio(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Resample(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .ModelLoad(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Inference(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InputTooLong(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .IncompleteOutput(
            kind: try FfiConverterTypeIncompleteOutputKind.read(from: &buf),
            partialText: try FfiConverterOptionString.read(from: &buf)
            )
        case 8: return .Cancelled(
            partialText: try FfiConverterOptionString.read(from: &buf)
            )
        case 9: return .FileHash(
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .FileSizeMismatch(
            expected: try FfiConverterUInt64.read(from: &buf),
            actual: try FfiConverterUInt64.read(from: &buf)
            )
        case 11: return .FileHashMismatch(
            expected: try FfiConverterString.read(from: &buf),
            actual: try FfiConverterString.read(from: &buf)
            )
        case 12: return .InvalidExpectedSha256(
            message: try FfiConverterString.read(from: &buf)
            )
        case 13: return .InvalidModelPackageManifest
        case 14: return .Busy

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {





        case let .AudioRead(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)


        case let .UnsupportedAudio(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)


        case let .Resample(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)


        case let .ModelLoad(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)


        case let .Inference(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)


        case let .InputTooLong(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)


        case let .IncompleteOutput(kind,partialText):
            writeInt(&buf, Int32(7))
            FfiConverterTypeIncompleteOutputKind.write(kind, into: &buf)
            FfiConverterOptionString.write(partialText, into: &buf)


        case let .Cancelled(partialText):
            writeInt(&buf, Int32(8))
            FfiConverterOptionString.write(partialText, into: &buf)


        case let .FileHash(message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(message, into: &buf)


        case let .FileSizeMismatch(expected,actual):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(expected, into: &buf)
            FfiConverterUInt64.write(actual, into: &buf)


        case let .FileHashMismatch(expected,actual):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(expected, into: &buf)
            FfiConverterString.write(actual, into: &buf)


        case let .InvalidExpectedSha256(message):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(message, into: &buf)


        case .InvalidModelPackageManifest:
            writeInt(&buf, Int32(13))


        case .Busy:
            writeInt(&buf, Int32(14))

        }
    }
}


